function kin = getKinematics(obj,me,params)

% ----------------------------------------------
% -- Check if obj already has kin --
% ----------------------------------------------
if isfield(obj,'kin')
    if isfield(params,'reload_kin')
        if params.reload_kin
            % get kinematics
        else
            return % kin = obj.kin
        end
    end
    return % kin = obj.kin
else
    % get kinematics
end


% ----------------------------------------------
% -- Kinematics --
% (xdisp,ydisp,xvel,yvel) for each dlc feature
% ----------------------------------------------
[kin.dat,kin.featLeg,kin.nans] = getKinematicsFromVideo(obj,params);

% ----------------------------------------------
% -- Tongue angle and length --
% ----------------------------------------------
if ismember('tongue',params.traj_features{1})
    [ang,len] = getLickAngleAndLength(kin.featLeg,kin.dat,kin.nans);
    kin.featLeg{end+1} = 'tongue_angle';
    kin.featLeg{end+1} = 'tongue_length';

    kin.dat(:,:,end+1) = ang;
    kin.dat(:,:,end+1) = len;
end

% ----------------------------------------------
% -- Motion energy --
% ----------------------------------------------
kin.featLeg{end+1} = 'motion_energy';

kin.dat(:,:,end+1) = me.data;

% ----------------------------------------------
% -- Standardize kinematics --
% ----------------------------------------------
for featix = 1:size(kin.dat,3)
    temp = kin.dat(:,:,featix);
    temp2 = temp(:);
    kin.dat_std(:,:,featix) = (temp - mean(temp2,'omitnan')) ./ std(temp2,'omitnan'); 
end

% ----------------------------------------------
% -- DIMENSIONALITY REDUCTION --
% ----------------------------------------------
% many of the video features will be highly correlated, so we will perform PCA/FA
% on the matrix of features to reduce the dimensionality to a set of factors that
% best explain the movement captured by the video recordings
kin.dat_reduced = reduceDimensionVideoFeatures(kin.dat,params.feat_varToExplain);

end

function [xvel, yvel] = findVelocity(xpos, ypos, feat)


for i = 1:size(xpos,2) % for each trial
    tsinterp = [xpos(:,i) ypos(:,i)];
    basederiv = median(diff(tsinterp),'omitnan');

    % find the difference between the feat velocity and the
    % baseline feature velocity (NOT FOR TONGUE)
    xvel(:,i) = gradient(tsinterp(:,1));
    yvel(:,i) = gradient(tsinterp(:,2));
    if ~contains(feat,'tongue') %|| strcmp(traj(trix).featNames{feat},'nose')
        xvel(:,i) = xvel(:,i) - basederiv(1);
        yvel(:,i) = yvel(:,i) - basederiv(1);
    end

    % fill missing values for all features
    if ~contains(feat,'tongue')
        xvel(:,i) = fillmissing(xvel(:,i),'nearest');
        yvel(:,i) = fillmissing(yvel(:,i),'nearest');
    else
        tempx = xvel(:,i);
        tempx(isnan(tempx)) = 0; % set tongue velocity to 0 if not visible
        xvel(:,i) = tempx;
        tempy = yvel(:,i);
        tempy(isnan(tempy)) = 0; % set tonge velocity to 0 if not visible
        yvel(:,i) = tempy;
    end
end


end  % findVelocity





